# matrix_add :: ([[1, 2], [3, 4]], [[5, 6], [7, 8]])
def matrix_add(a, b):
    return [[x + y for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]

if __name__ == "__main__":
    print(matrix_add(([[1, 2], [3, 4]], [[5, 6], [7, 8]])))

